+        store
+            .store("http:test", "template1", "good content", 3600)
+            .unwrap();
+
+        // Corrupt the metadata file
+        let meta_path = store
+            .content_path("http:test", "template1")
+            .with_extension("meta.json");
+        fs::write(&meta_path, "not valid json {{{").unwrap();
+
+        // load() should return None, not an error
+        let result = store.load("http:test", "template1").unwrap();
+        assert!(result.is_none());
+    }
+
+    #[test]
+    fn no_temp_files_left_after_store() {
+        let temp = TempDir::new().unwrap();
+        let store = CacheStore::new(temp.path());
+
+        store
+            .store("http:test", "template1", "content", 3600)
+            .unwrap();
+
+        // Check that no .tmp files remain
+        let tmp_files: Vec<_> = fs::read_dir(temp.path())
+            .unwrap()
+            .filter_map(|e| e.ok())
+            .filter(|e| e.file_name().to_string_lossy().starts_with(".tmp."))
+            .collect();
+        assert!(tmp_files.is_empty(), "temp files should be cleaned up");
+    }
